function dump(node, depth) {
  let s = "  ".repeat(depth) + node.type + " | " + node.name + " | " + Math.round(node.width) + "x" + Math.round(node.height);
  if (node.type === "TEXT") {
    s += " | chars=" + JSON.stringify(node.characters.slice(0,60)) + " | font=" + JSON.stringify(node.fontName) + " | size=" + node.fontSize;
  }
  if ("fills" in node && Array.isArray(node.fills) && node.fills.length) {
    s += " | fills=" + JSON.stringify(node.fills.map(f=>f.type==="SOLID"?f.color:f.type));
  }
  if ("strokes" in node && node.strokes && node.strokes.length) s += " | strokes=" + JSON.stringify(node.strokes.map(f=>f.color));
  if ("cornerRadius" in node && node.cornerRadius) s += " | r=" + node.cornerRadius;
  if (node.type === "COMPONENT" || node.type === "COMPONENT_SET") s += " | id=" + node.id;
  if ("children" in node && depth < 4) {
    for (const c of node.children) s += "\n" + dump(c, depth+1);
  }
  return s;
}
