function solid(c, o) { return [{type:"SOLID", color:c, opacity: o===undefined?1:o}]; }
async function mkT(parent, chars, font, size, color, opts) {
  opts = opts || {};
  const t = figma.createText();
  t.fontName = font; t.fontSize = size; t.characters = chars;
  t.fills = solid(color);
  if (opts.lh) t.lineHeight = {value: opts.lh, unit:"PIXELS"};
  if (opts.name) t.name = opts.name;
  parent.appendChild(t);
  return t;
}
function iconIn(parent, compId, size, color) {
  const comp = figma.getNodeById(compId);
  const inst = comp.createInstance();
  inst.resize(size, size);
  parent.appendChild(inst);
  const paint = solid(color);
  inst.findAll(function(n){ return n.type === "VECTOR" || n.type === "ELLIPSE" || n.type === "RECTANGLE" || n.type === "LINE"; }).forEach(function(n){ try { n.fills = paint; } catch(e){} });
  return inst;
}
function iconBtn(parent, iconId, variant, color) {
  const b = figma.createComponent();
  b.name = "Icon Button/" + variant;
  b.resize(44, 44);
  b.cornerRadius = 22;
  b.fills = variant === "Filled" ? solid(C.brand) : solid(C.surface);
  if (variant !== "filled") { b.strokes = solid(C.border); b.strokeWeight = 1; }
  b.layoutMode = "HORIZONTAL";
  b.primaryAxisAlignItems = "CENTER";
  b.counterAxisAlignItems = "CENTER";
  parent.appendChild(b);
  iconIn(b, iconId, 22, color);
  return b;
}

