function dump(n, d) {
  let s = "  ".repeat(d) + n.id + " | " + n.type + " | " + n.name;
  if (n.type === "TEXT") s += " | '" + n.characters + "'";
  if ("children" in n) for (const c of n.children) s += "\n" + dump(c, d+1);
  return s;
}
